Read file tv/app/src/main/java/com/openquizgo/guard/platform/LogStore.kt, lines 1-72
1: package com.openquizgo.guard.platform
2: 
3: import java.io.File
4: import java.io.FileOutputStream
5: import java.text.SimpleDateFormat
6: import java.util.Date
7: import java.util.Locale
8: import java.util.TimeZone
9: 
10: /**
11:  * 应用私有目录下的滚动日志文件（049）。
12:  *
13:  * - 写入 `files/logs/guard.log`，单文件上限 [MAX_BYTES]（1MB）；
14:  * - 超出后轮转为 `guard.log.1`，只保留一份备份；
15:  * - 所有入口线程安全，任何 IO/权限异常都会被吞掉，不影响主流程。
16:  *
17:  * 不依赖 Android API，便于在 JVM 单元测试中使用临时目录验证。
18:  */
19: class LogStore(
20:     private val logDir: File,
21:     private val maxBytes: Long = MAX_BYTES,
22: ) {
23:     private val logFile = File(logDir, FILE_NAME)
24:     private val rotatedFile = File(logDir, ROTATED_FILE_NAME)
25:     private val timeFormat = SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS", Locale.US).apply {
26:         timeZone = TimeZone.getDefault()
27:     }
28: 
29:     @Synchronized
30:     fun write(level: String, tag: String, message: String) {
31:         runCatching {
32:             val bytes = buildLine(level, tag, message).toByteArray(Charsets.UTF_8)
33:             val payload = if (bytes.size > maxBytes) {
34:                 bytes.copyOf(maxBytes.coerceAtMost(Int.MAX_VALUE.toLong()).toInt())
35:             } else {
36:                 bytes
37:             }
38:             if (!logDir.exists()) logDir.mkdirs()
39:             if (logFile.length() > 0 && logFile.length() + payload.size > maxBytes) {
40:                 rotate()
41:             }
42:             FileOutputStream(logFile, true).use { it.write(payload) }
43:         }
44:     }
45: 
46:     private fun buildLine(level: String, tag: String, message: String): String {
47:         val safeTag = tag.replace('\n', ' ').replace('\r', ' ').take(MAX_TAG_CHARS)
48:         val safeMessage = message.replace('\n', ' ').replace('\r', ' ').take(MAX_MESSAGE_CHARS)
49:         return "${timeFormat.format(Date())} $level/$safeTag $safeMessage\n"
50:     }
51: 
52:     private fun rotate() {
53:         if (rotatedFile.exists()) rotatedFile.delete()
54:         if (!logFile.renameTo(rotatedFile)) {
55:             // 某些文件系统不允许 rename 覆盖，退化为复制后清空当前文件。
56:             runCatching {
57:                 logFile.copyTo(rotatedFile, overwrite = true)
58:                 logFile.delete()
59:             }
60:         }
61:     }
62: 
63:     companion object {
64:         const val DIRECTORY = "logs"
65:         const val FILE_NAME = "guard.log"
66:         const val ROTATED_FILE_NAME = "guard.log.1"
67:         const val MAX_BYTES = 1024L * 1024L
68: 
69:         private const val MAX_TAG_CHARS = 64
70:         private const val MAX_MESSAGE_CHARS = 8 * 1024
71:     }
72: }
